var t=`0162-pasta-allamatriciana`;var i=`world-0162`;var n=`IT`;var o=`southern-europe`;var s=4;var r=39;var l={en:`Pasta all'Amatriciana`,ua:`Паста аматричана`};var u={en:`A classic dish from Italy, featuring guanciale, bucatini, pecorino romano. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Італія. Основні складники: гуанчале, букатіні, пекоріно романо. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var c=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 9 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 9 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:9,i:[[`guanciale`,180,`g`],[`extra-virgin-olive-oil`,20,`ml`]]},{en:`Cook the listed sauce ingredients over medium-low heat for about 15 minutes until aromatic and slightly thickened.`,ua:`Готуйте складники соусу на помірно слабкому вогні приблизно 15 хвилин до появи аромату та легкого загустіння.`,t:[`sauteing`,`reducing-sauce`],m:15,i:[[`tomato-passata`,460,`g`],[`hot-paprika`,3,`g`]]},{en:`Cook the pasta in generously salted boiling water for about 11 minutes until al dente; reserve a cup of its starchy water.`,ua:`Варіть пасту в добре підсоленій киплячій воді приблизно 11 хвилин до стану аль денте; збережіть чашку крохмалистої води.`,t:[`pasta-boiling`],m:11,i:[[`bucatini`,380,`g`],[`water`,1700,`ml`],[`table-salt`,10,`g`]]},{en:`Toss the pasta with the tomato and guanciale sauce over low heat. Sprinkle with Pecorino Romano and serve immediately.`,ua:`Змішайте пасту з томатним соусом і гуанчале на слабкому вогні. Посипте пекоріно романо й одразу подавайте.`,t:[`pasta-finishing-in-sauce`,`tossing`],m:4,i:[[`pecorino-romano`,95,`g`]]}];var g={slug:t,id:i,country:`IT`,region:o,servings:4,minutes:39,title:l,text:u,steps:c};export{n as country,g as default,i as id,r as minutes,o as region,s as servings,t as slug,c as steps,u as text,l as title};